def cycpattern_check(a, b):
    if not b:
        return True

    def generate_cyclic_permutations(s):
        result = []
        for i in range(len(s)):
            result.append(s[i:] + s[:i])
        return result

    def is_substring(s1, s2):
        return s2 in s1

    if is_substring(a, b):
        return True

    cyclic_permutations = generate_cyclic_permutations(b)
    for perm in cyclic_permutations:
        if is_substring(a, perm):
            return True

    return False
