    roman_dict = {
        1: 'i', 4: 'iv', 5: 'v', 9: 'ix',
        10: 'x', 40: 'xl', 50: 'l', 90: 'xc',
        100: 'c', 400: 'cd', 500: 'd', 900: 'cm',
        1000: 'm'
    }

    if not 1 <= number <= 1000:
        return "Number out of range"

    result = ""
    for value, numeral in sorted(roman_dict.items(), key=lambda x: x[0], reverse=True):
        while number >= value:
