from typing import List

def filter_by_substring(strings: List[str], substring: str) -> List[str]:
    """ Filter an input list of strings for those containing the given substring.
    The search is case-sensitive and requires complete matches of the substring.
    >>> filter_by_substring([], 'a')
    []
    >>> filter_by_substring(['abc', 'bacd', 'cde', 'array'], 'a')
    ['abc', 'bacd', 'array']
    Ensure that the substring is non-empty before proceeding with the filtering.
    """
    if not substring:
        return []

    return [s for s in strings if substring in s]

