from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ Given a list of integers, compute and return a tuple consisting of the sum and the product of all integers in the list.
    If the list is empty, the sum should be 0 and the product should be 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    The function should be able to process lists with both negative and positive numbers.
    """

    if not numbers:
        return (0, 1)

    sum_result = 0
    product_result = 1

    for num in numbers:
        sum_result += num
        product_result *= num

    return (sum_result, product_result)
