def int_to_mini_roman(number):
    roman_dict = {
        1: 'i', 4: 'iv', 5: 'v', 9: 'ix',
        10: 'x', 40: 'xl', 50: 'l', 90: 'xc',
        100: 'c', 400: 'cd', 500: 'd', 900: 'cm',
        1000: 'm'
    }

    if not 1 <= number <= 1000:
        return "Number out of range"

    result = ""
    for key in sorted(roman_dict.keys(), reverse=True):
        while number >= key:
            result += roman_dict[key]
            number -= key

    return result
